UPDATE bible_verses SET text = 'If she is a wall, we will build on her a turret of silver. If she is a door, we will enclose her with boards of cedar.' WHERE translation_id = @translation AND book_id = @book AND chapter = 8 AND verse = 9 AND verse_suffix = '' AND text = 'If she is a wall, we will build on her a turret of silver. If she is a door, we will enclose her with boards of cedar. Beloved';
UPDATE bible_verses SET text = 'My own vineyard is before me. The thousand are for you, Solomon, two hundred for those who tend its fruit.' WHERE translation_id = @translation AND book_id = @book AND chapter = 8 AND verse = 12 AND verse_suffix = '' AND text = 'My own vineyard is before me. The thousand are for you, Solomon, two hundred for those who tend its fruit. Lover';
UPDATE bible_verses SET text = 'You who dwell in the gardens, with friends in attendance, let me hear your voice!' WHERE translation_id = @translation AND book_id = @book AND chapter = 8 AND verse = 13 AND verse_suffix = '' AND text = 'You who dwell in the gardens, with friends in attendance, let me hear your voice! Beloved';
